<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { TableColumn } from '@nuxt/ui'
import type { SampleData, Tenant } from '../types'
import { notify, switchRole } from '../state'
import Icon from './Icon.vue'
const props = defineProps<{ data: SampleData }>()
const scopeOpen = ref(false)
const query = ref(''), filter = ref('all'), drawer = ref(false), selected = ref<Tenant>(), tab = ref('overview'), quota = ref(0)
const saved = ref<Tenant[]>([]), saving = ref(false)
const overrides = computed(() => Object.fromEntries(saved.value.filter(t => t.raw.prototypeLocalOnly).map(t => [t.id, t.aiWeeklyQuota])))
const tenants = computed(() => saved.value.length ? saved.value : props.data.factories)
async function refresh() { const response = await fetch('/__v5/data'); if (!response.ok) throw Error('无法回读本机工厂目录'); const data: SampleData = await response.json(); saved.value = data.factories }
onMounted(() => refresh().catch(e => notify(e.message)))
const rows = computed(() => tenants.value.filter(t => `${t.name} ${t.id}`.toLowerCase().includes(query.value.toLowerCase()) && (filter.value === 'all' || filter.value === 'active' && t.isActive || filter.value === 'inactive' && !t.isActive)))
const active = computed(() => tenants.value.filter(t => t.isActive).length)
const columns: TableColumn<Tenant>[] = [{ accessorKey: 'name', header: '工厂 / 租户' }, { accessorKey: 'type', header: '业态' }, { accessorKey: 'isActive', header: '状态' }, { accessorKey: 'aiWeeklyQuota', header: 'AI 周配额' }, { accessorKey: 'contactName', header: '联系人' }, { id: 'actions', header: '' }]
function open(t: Tenant, mode = 'overview') { selected.value = t; quota.value = t.aiWeeklyQuota ?? 0; tab.value = mode; drawer.value = true }
async function save() { if (!selected.value || saving.value) return; if (!Number.isInteger(quota.value) || quota.value < 0) return notify('配额需为大于等于 0 的整数。'); saving.value = true; const id=selected.value.id; try { const response=await fetch('/__v5/business/platform/api/platform/factories/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({aiWeeklyQuota:quota.value})}); const result=await response.json(); if(!response.ok||!result.success) throw Error(result.message||'保存失败'); await refresh(); const actual=tenants.value.find(t=>t.id===id); if(actual?.aiWeeklyQuota!==quota.value) throw Error('配额回读不一致'); selected.value=actual; notify(`已保存 ${id} 的本机配置并回读确认。`) } catch(e) { notify(e instanceof Error?e.message:'配置保存失败，请重试。') } finally {saving.value=false} }
const count = (key: string) => typeof props.data.platformStats[key] === 'number' ? String(props.data.platformStats[key]) : '—'
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">PLATFORM GOVERNANCE</div><h1>平台治理</h1><p>管理租户与平台配置，让工厂业务回到各自的工作区。</p></div><div class="head-actions"><span class="scope-label"><Icon name="shield" :size="15" />平台级范围 · 未进入工厂业务</span><UButton color="neutral" variant="outline" @click="scopeOpen = true"><Icon name="book" :size="16" />治理范围</UButton></div></div>
  <div class="platform-welcome"><div><span class="eyebrow">A CLEARER WORKSPACE</span><h2>平台管治理，工厂管经营。</h2><p>这里呈现真实租户目录与平台配置。生产计划、库存办理、工资和销售待办由工厂账号处理。</p><div><span><Icon name="check" :size="14" />明确角色</span><span><Icon name="check" :size="14" />选厂配置</span><span><Icon name="check" :size="14" />保留操作边界</span></div></div><div class="governance-diagram"><div class="diagram-platform"><Icon name="shield" :size="19" />CRETAS 平台</div><div class="diagram-line" /><div class="diagram-tenants"><span><Icon name="factory" />F006</span><span><Icon name="factory" />LIUSHANMEN</span><span><Icon name="factory" />其他租户</span></div></div></div>
  <div class="metrics-strip platform-metrics"><div><span>已收录工厂</span><strong>{{ tenants.length }}<small>家</small></strong></div><div><span><i class="dot green" />启用状态</span><strong>{{ active }}<small>家</small></strong></div><div><span>平台用户 · 源统计</span><strong>{{ count('totalUsers') === '—' ? count('userCount') : count('totalUsers') }}<small>人</small></strong></div><div><span>备份目录记录</span><strong>{{ data.backups.length }}<small>条</small></strong></div></div>
  <section class="surface tenant-directory"><div class="section-tools"><div><h3>工厂与租户</h3><p class="muted">平台账号目录 · {{ data.snapshotUpdatedAt.slice(0, 10) }} 快照</p></div><div class="directory-tools"><div class="search-field"><Icon name="search" :size="16" /><UInput v-model="query" placeholder="搜索名称或工厂 ID…" aria-label="搜索工厂" /></div><USelect v-model="filter" :items="[{ label: '全部状态', value: 'all' }, { label: '已启用', value: 'active' }, { label: '未启用', value: 'inactive' }]" aria-label="筛选工厂状态" /></div></div>
    <UTable :data="rows" :columns="columns" class="tenant-table" :ui="{ th: 'text-xs font-medium text-muted', td: 'text-sm' }" data-testid="tenant-table"><template #name-cell="{ row }"><button class="tenant-cell" @click="open(row.original)"><span class="tenant-avatar"><Icon name="factory" :size="19" /></span><span><strong>{{ row.original.name }}</strong><small>{{ row.original.id }}</small></span></button></template><template #type-cell="{ row }"><span class="muted">{{ row.original.raw.typeDisplayName || row.original.type }}</span></template><template #isActive-cell="{ row }"><span :class="['status-badge', row.original.isActive ? 'green' : 'gray']"><i />{{ row.original.isActive ? '已启用' : '未启用' }}</span></template><template #aiWeeklyQuota-cell="{ row }"><b class="number">{{ row.original.aiWeeklyQuota ?? '—' }}</b><span v-if="row.original.aiWeeklyQuota != null" class="unit">次 / 周</span><span v-if="overrides[row.original.id] != null" class="local-tag">草稿</span></template><template #contactName-cell="{ row }"><span>{{ row.original.contactName || '未提供' }}</span></template><template #actions-cell="{ row }"><div class="table-actions"><button class="table-link" @click="open(row.original)">查看</button><button class="table-link" @click="open(row.original, 'config')">配置<Icon name="chevron" :size="13" /></button></div></template><template #empty><div class="empty-block"><Icon name="search" :size="28" /><p>没有匹配的租户，调整名称或状态后重试。</p></div></template></UTable><div class="table-footer"><span><Icon name="shield" :size="14" />其他租户仅展示其真实目录资料，不套用 F006 业务记录。</span><span>{{ rows.length }} / {{ tenants.length }} 家</span></div>
  </section>
  <div class="governance-bottom"><section class="surface governance-boundary"><span class="small-square"><Icon name="settings" :size="20" /></span><div><h3>工厂配置先明确对象</h3><p>AI 配额、编码规则和连接配置可能按工厂保存；平台身份不代表这些数据都是全局。</p></div><UButton color="neutral" variant="ghost" @click="open(tenants.find(t => t.id === 'F006') || tenants[0], 'config')">查看 F006 配置<Icon name="arrow" :size="16" /></UButton></section><section class="surface governance-boundary"><span class="small-square"><Icon name="plans" :size="20" /></span><div><h3>查看工厂经营样板</h3><p>显式切换为 f006_admin 的工厂超级管理员视角，查看生产、分析与 AI。</p></div><UButton color="neutral" variant="ghost" @click="switchRole('factory')">切换工厂账号<Icon name="arrow" :size="16" /></UButton></section></div>

<UModal v-model:open="scopeOpen" title="平台治理范围" description="平台治理与工厂业务的工作区边界"><template #body><div class="scope-matrix"><div><b>平台管理员</b><p>租户目录、平台用户、平台配置与租户配额。当前样板支持逐厂查看源字段和保存配额草稿。</p></div><div><b>工厂超级管理员</b><p>工厂内生产计划、工序、库存、销售、成本和 AI 业务。进入这些页面会明确切换到 F006 工作区。</p></div></div><UButton color="neutral" variant="outline" @click="scopeOpen = false; switchRole('factory')">切换工厂工作区</UButton></template></UModal>
  <USlideover v-model:open="drawer" :title="selected?.name || '工厂资料'" :description="selected?.id + ' · 平台选厂工作区'" :ui="{ content: 'max-w-lg' }"><template #body><template v-if="selected"><div class="tab-list drawer-tabs"><button :class="{ active: tab === 'overview' }" @click="tab = 'overview'">工厂资料</button><button :class="{ active: tab === 'config' }" @click="tab = 'config'">配置草稿</button><button :class="{ active: tab === 'raw' }" @click="tab = 'raw'">全部源字段</button></div><div v-if="tab === 'overview'" class="tenant-detail"><div class="context-factory"><span class="tenant-avatar large"><Icon name="factory" :size="28" /></span><div><h2>{{ selected.name }}</h2><span :class="['status-badge', selected.isActive ? 'green' : 'gray']"><i />{{ selected.isActive ? '已启用' : '未启用' }}</span></div></div><div v-for="(value, label) in { '工厂 ID': selected.id, '业态': selected.raw.typeDisplayName || selected.type, '联系人': selected.contactName || '未提供', '地址': selected.raw.address || '未提供', '创建时间': selected.raw.createdAt || '未提供' }" :key="label" class="property-pair"><span>{{ label }}</span><b>{{ value }}</b></div><div class="source-note"><Icon name="book" /><div>平台目录原始记录<small>GET /api/platform/factories</small><p>当前展示目录和配置，不推断该租户的产量、销售或人员情况。</p></div></div></div><div v-else-if="tab === 'config'" class="tenant-config"><span class="scope-label"><Icon name="shield" :size="15" />目标工厂：{{ selected.id }}</span><h2>AI 周配额</h2><p>编辑仅保存在本机，源平台配额不变。</p><UInputNumber v-model="quota" :min="0" :step="1" :format-options="{ maximumFractionDigits: 0 }" aria-label="AI周配额" /><UButton @click="save" data-testid="save-quota">保存本机配置草稿</UButton><p class="muted">原始值：{{ data.factories.find(t => t.id === selected?.id)?.aiWeeklyQuota ?? '未提供' }} 次／周</p></div><div v-else class="raw-fields"><div v-for="(v, k) in selected.raw" :key="k"><span>{{ k }}</span><code>{{ v === null ? 'null（未提供）' : typeof v === 'object' ? JSON.stringify(v) : v }}</code></div></div></template></template></USlideover>
</template>
